import XCTest

class BlueskyTestUITests: XCTestCase {
    let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")

    func testReplyToFirstPost() {
        // Activate the Bluesky app
        app.activate()

        // Wait for the app to stabilize
        sleep(1)

        // Find all text elements to locate the first post
        let staticTexts = app.staticTexts
        var foundPost = false

        // Look for the "Mochi napping" text in the first post
        for element in staticTexts.allElementsBoundByAccessibilityElement {
            if element.label.contains("Mochi") {
                foundPost = true
                break
            }
        }

        if foundPost {
            print("Found first post!")

            // Now find the reply button - it's usually near the post content
            // Try to find buttons with accessibility hints or labels containing "reply"
            let buttons = app.buttons
            var replyButton: XCUIElement?

            // Look for the first interactive button that might be a reply button
            for (index, button) in buttons.allElementsBoundByAccessibilityElement.enumerated() {
                let label = button.label.lowercased()
                // Reply buttons often have no label or have "reply" in the hint
                if label.contains("reply") || (index < 50 && label.isEmpty) {
                    replyButton = button
                    break
                }
            }

            if let replyBtn = replyButton {
                print("Found reply button")
                replyBtn.tap()
                sleep(1)

                // Find the text input field
                let textInputs = app.textViews
                if textInputs.count > 0 {
                    let textInput = textInputs.firstMatch
                    textInput.tap()
                    textInput.typeText("nice one")
                    sleep(1)

                    // Find and tap the send button
                    let sendButtons = app.buttons.matching(NSPredicate(format: "label LIKE '*Send*' || label LIKE '*send*'"))
                    if sendButtons.count > 0 {
                        sendButtons.firstMatch.tap()
                        print("Reply sent!")
                    } else {
                        // Try pressing Return as an alternative
                        XCUIApplication().typeText("\r")
                        print("Tried sending with Return key")
                    }
                }
            }
        }
    }
}
EOF

